21	/// The project's single `get_it` instance — exactly one DI container exists
22	/// (architecture spine). Every feature's `registerXFeature()` registers
23	/// through this same `sl`, never a second container.
24	final sl = GetIt.instance;
25	
26	/// Bootstraps core infrastructure: loads `.env`, then registers
27	/// `FlutterSecureStorage`, `Dio` (configured with the header + retry
28	/// interceptors) and `ApiClient` through `sl` — the `dio` +
29	/// `flutter_secure_storage` + `get_it` integration spike this story proves
30	/// before anything else is built on top of it.
31	Future<void> setupCoreDependencies() async {
32	  await dotenv.load(fileName: '.env');
33	
34	  final functionsBaseUrl = dotenv.get('FUNCTIONS_BASE_URL');
35	  final supabaseAnonKey = dotenv.get('SUPABASE_ANON_KEY');
36	
37	  sl.registerLazySingleton<FlutterSecureStorage>(
38	    () => const FlutterSecureStorage(),
39	  );
40	
41	  sl.registerLazySingleton<AccessTokenProvider>(
42	    () => SecureStorageAccessTokenProvider(sl<FlutterSecureStorage>()),
43	  );
44	
45	  sl.registerLazySingleton<UrlBuilder>(() => UrlBuilder(functionsBaseUrl));
46	
47	  // Story 1.5 — `dispose:` wires `SessionExpiryNotifier.dispose()` into
48	  // `get_it`'s own reset lifecycle, same rationale as `SessionRepository`'s
49	  // own registration below. Registration order here is cosmetic, not
50	  // load-bearing: `registerLazySingleton` only builds its instance on first
51	  // `sl<T>()` access, so `ApiClient`'s factory can resolve this dependency
52	  // correctly regardless of which of the two is registered first.
53	  sl.registerLazySingleton<SessionExpiryNotifier>(
54	    () => SessionExpiryNotifierImpl(),
55	    dispose: (notifier) => notifier.dispose(),
56	  );
57	
58	  sl.registerLazySingleton<Dio>(() {
59	    final dio = Dio(
60	      BaseOptions(
61	        // Design note (docs/input is silent on exact numbers): a stalled
