3	/// `EntriesRepository.list()`'s return shape — one page of [items] plus the
4	/// server's own opaque [nextCursor] (`null` once there is no further page,
5	/// `openapi.yaml`'s `entries-list` `meta.nextCursor`). The Hive-fallback
6	/// path (`EntriesRepositoryImpl.list()`) always returns `nextCursor: null`
7	/// (Boundaries) — a cached dump has no further page to request.
8	class EntriesPage {
9	  const EntriesPage({required this.items, required this.nextCursor});
10	
11	  final List<Entry> items;
12	  final String? nextCursor;
13	
14	  @override
15	  bool operator ==(Object other) =>
16	      identical(this, other) ||
17	      (other is EntriesPage &&
18	          other.nextCursor == nextCursor &&
19	          _listEquals(other.items, items));
20	
21	  @override
22	  int get hashCode => Object.hash(Object.hashAll(items), nextCursor);
23	
24	  @override
25	  String toString() =>
26	      'EntriesPage(items: ${items.length}, nextCursor: $nextCursor)';
27	}
28	
29	bool _listEquals(List<Entry> a, List<Entry> b) {
30	  if (a.length != b.length) {
31	    return false;
32	  }
33	  for (var i = 0; i < a.length; i++) {
34	    if (a[i] != b[i]) {
35	      return false;
36	    }
37	  }
38	  return true;
39	}
