99	/// Collects every state the cubit emits for the duration of [act] — same
100	/// helper/rationale `auth_cubit_test.dart` already documents: this stack
101	/// has no `bloc_test` pin, so this drives [EntriesSearchCubit] through its
102	/// public API only, the same way any other `flutter_bloc` consumer would.
103	Future<List<Resource<List<Entry>>>> _emittedDuring(
104	  EntriesSearchCubit cubit,
105	  FutureOr<void> Function() act,
106	) async {
107	  final emitted = <Resource<List<Entry>>>[];
108	  final subscription = cubit.stream.listen(emitted.add);
109	  await act();
110	  await subscription.cancel();
111	  return emitted;
112	}
