28	/// A trivial fake `PendingEntryWriteTracker` — this suite drives `load()`
29	/// directly, never through a `confirmedWrites` event
30	/// (`dashboard_cubit_test.dart`'s own job).
31	class _NoOpPendingEntryWriteTracker implements PendingEntryWriteTracker {
32	  @override
33	  Future<Either<Failure, Entry>> create({
34	    required String content,
35	    required EntrySource source,
36	    int? mediaDurationSeconds,
37	  }) async => throw UnimplementedError('not expected to be called');
38	
39	  @override
