1	import 'dart:async';
2	
3	import 'package:flutter/material.dart';
4	import 'package:flutter_test/flutter_test.dart';
5	import 'package:fpdart/fpdart.dart';
6	import 'package:go_router/go_router.dart';
7	
8	import 'package:cerne/core/failure/failure.dart';
9	import 'package:cerne/core/widgets/back_arrow_header.dart';
10	import 'package:cerne/features/account/domain/repositories/account_settings_repository.dart';
11	import 'package:cerne/features/account/presentation/cubit/account_settings_cubit.dart';
12	import 'package:cerne/features/account/presentation/screens/account_settings_screen.dart';
13	import 'package:cerne/features/dashboard/domain/entities/dashboard_aggregate.dart';
14	import 'package:cerne/features/dashboard/domain/repositories/dashboard_repository.dart';
15	import 'package:cerne/features/dashboard/presentation/cubit/dashboard_cubit.dart';
16	import 'package:cerne/features/entries/domain/entities/entry.dart';
17	import 'package:cerne/features/entries/domain/entities/pending_entry_write.dart';
18	import 'package:cerne/features/entries/domain/services/pending_entry_write_tracker.dart';
19	
20	/// Same plain (non-mocktail) fake shape as
21	/// `account_settings_cubit_test.dart`'s own `_FakeAccountSettingsRepository`
22	/// — this suite needs a scriptable `setBiometricEnabled()` result plus a
23	/// real stream the cubit (built from this fake, not mocked) actually
24	/// subscribes to. `biometricEnabledStream` is a plain broadcast stream, not
25	/// a `Stream.multi` replay wrapper (unlike the production repository) —
26	/// `AccountSettingsCubit`'s own constructor already reads
27	/// [currentBiometricEnabled] directly for its initial state, so no replay
28	/// machinery is needed for a fake with exactly one subscriber.
29	class _FakeAccountSettingsRepository implements AccountSettingsRepository {
30	  bool _value = true;
31	  final _controller = StreamController<bool>.broadcast();
32	
33	  /// The next `setBiometricEnabled()` call's own result — defaults to a
34	  /// failure so a test must opt in to the success path explicitly, same
35	  /// convention as the cubit-level fake.
36	  Either<Failure, Unit> setBiometricEnabledResult = left(
37	    const Failure.malformedResponse(message: 'fake: not configured'),
38	  );
39	
40	  /// Lets a test hold `setBiometricEnabled()` unresolved, to observe
41	  /// `state.isSaving` mid-flight (review finding: the `Switch` must
42	  /// disable itself while a toggle is in flight).
43	  Completer<void>? setBiometricEnabledGate;
44	
45	  @override
46	  bool get currentBiometricEnabled => _value;
47	
48	  @override
49	  Stream<bool> get biometricEnabledStream => _controller.stream;
50	
51	  @override
52	  Future<Either<Failure, Unit>> fetchBiometricEnabled() async => right(unit);
53	
54	  @override
55	  Future<Either<Failure, Unit>> setBiometricEnabled(bool enabled) async {
56	    final gate = setBiometricEnabledGate;
57	    if (gate != null) {
58	      await gate.future;
59	    }
60	    final previous = _value;
61	    _emit(enabled);
62	    final result = setBiometricEnabledResult;
63	    if (result.isLeft()) {
64	      _emit(previous);
65	    }
66	    return result;
67	  }
68	
69	  @override
70	  Future<void> dispose() => _controller.close();
71	
72	  void _emit(bool value) {
73	    _value = value;
74	    _controller.add(value);
75	  }
76	}
77	
78	/// spec-8-1 — a trivial fake [DashboardRepository]: this suite only needs
79	/// `AccountSettingsScreen.initState`'s own unconditional `dashboardCubit.
80	/// load()` call to resolve without throwing (`dashboard_cubit_test.dart`/
81	/// `dashboard_chart_section_test.dart` already cover the chart's own
82	/// behavior in isolation) — defaults to the zero-entries shape.
83	class _FakeDashboardRepository implements DashboardRepository {
84	  Either<Failure, DashboardAggregate> getAggregateResult = right(
85	    const DashboardAggregate(totalCount: 0, bucketCounts: []),
86	  );
87	
88	  @override
89	  Future<Either<Failure, DashboardAggregate>> getAggregate({
90	    required String period,
91	  }) async => getAggregateResult;
92	}
93	
94	/// A trivial fake `PendingEntryWriteTracker` — this suite never exercises
95	/// spec-8-1's own `confirmedWrites` recompute path, only that
96	/// `DashboardCubit`'s constructor subscription resolves without throwing.
97	class _UnusedPendingEntryWriteTracker implements PendingEntryWriteTracker {
98	  @override
99	  Future<Either<Failure, Entry>> create({
100	    required String content,
101	    required EntrySource source,
102	    int? mediaDurationSeconds,
103	  }) async => throw UnimplementedError('not expected to be called');
104	
105	  @override
106	  Future<void> retry(String tempId) async =>
107	      throw UnimplementedError('not expected to be called');
108	
109	  @override
110	  Stream<List<PendingEntryWrite>> get pendingWrites => const Stream.empty();
111	
112	  @override
113	  Stream<({String tempId, Entry entry})> get confirmedWrites =>
114	      const Stream.empty();
115	
116	  @override
117	  Future<void> dispose() async {}
118	}
119	
120	/// Builds a fresh [DashboardCubit] (backed by a fresh
121	/// [_FakeDashboardRepository]) and registers it for teardown — every test
122	/// below needs one to satisfy `AccountSettingsScreen`'s widened
123	/// constructor (spec-8-1), even the ones that otherwise only exercise the
124	/// biometric toggle.
125	DashboardCubit _buildDashboardCubit() {
126	  final cubit = DashboardCubit(
127	    _FakeDashboardRepository(),
128	    _UnusedPendingEntryWriteTracker(),
129	  );
130	  addTearDown(() => cubit.close());
131	  return cubit;
132	}
133	
134	/// `/configuracoes`'s `BackArrowHeader` does `context.go('/')`
135	/// (`back_arrow_header_test.dart`'s own rationale) — needs a real
136	/// `GoRouter` ancestor to resolve, hence this minimal two-route wrapper
137	/// rather than a bare `MaterialApp`.
138	GoRouter _routerWith(Widget screen) {
139	  return GoRouter(
140	    initialLocation: '/configuracoes',
141	    routes: [
142	      GoRoute(path: '/', builder: (context, state) => const Text('Home')),
143	      GoRoute(path: '/configuracoes', builder: (context, state) => screen),
144	    ],
145	  );
146	}
147	
148	/// Builds a fresh [_FakeAccountSettingsRepository] + [AccountSettingsCubit]
149	/// pair and pumps the real screen around it, registering both for cleanup.
150	///
151	/// Deliberately constructed *inside* each `testWidgets` body (via this
152	/// helper) rather than in a shared `setUp()` — `setUp()`'s callback runs in
153	/// `package:test`'s own per-test zone, a different zone than the one
154	/// `TestWidgetsFlutterBinding` establishes for the `testWidgets` callback
155	/// itself. A `StreamSubscription` (here, `AccountSettingsCubit`'s own
156	/// subscription to the repository's stream, set up in its constructor)
157	/// created in that outer zone does not reliably get its pending events
158	/// flushed by `tester.pump()`'s zone-scoped microtask draining — observed
159	/// directly: `cubit.state` updated correctly, but the `BlocBuilder`-driven
160	/// widget never rebuilt, no matter how many `pump()` calls followed.
161	/// Constructing the cubit here, inside the same zone `tester.pump()`
162	/// drains, avoids the mismatch entirely.
163	Future<(_FakeAccountSettingsRepository, AccountSettingsCubit)> _pumpScreen(
164	  WidgetTester tester,
165	) async {
166	  final fakeRepository = _FakeAccountSettingsRepository();
167	  final cubit = AccountSettingsCubit(fakeRepository);
168	  addTearDown(() => cubit.close());
169	  addTearDown(fakeRepository.dispose);
170	
171	  final router = _routerWith(
172	    AccountSettingsScreen(cubit: cubit, dashboardCubit: _buildDashboardCubit()),
173	  );
174	  addTearDown(router.dispose);
175	  await tester.pumpWidget(MaterialApp.router(routerConfig: router));
176	
177	  return (fakeRepository, cubit);
178	}
179	
180	/// Proves spec-2-4's Acceptance Criteria directly against the real screen
181	/// widget: "shows only the biometric toggle" (minimal), the toggle mirrors
182	/// the cubit's state, tapping it drives `toggleBiometric()`, and a failed
183	/// toggle's error message renders inline — `app_router_test.dart` already
184	/// proves the screen is *reachable*; this suite proves its own rendering
185	/// and interaction in isolation.
186	void main() {
187	  testWidgets(
188	    'shows the header titled Configurações and exactly one switch — no '
189	    'other content (AC: "shows only the biometric toggle")',
190	    (tester) async {
191	      await _pumpScreen(tester);
192	
193	      expect(find.byType(BackArrowHeader), findsOneWidget);
194	      expect(find.text('Configurações'), findsOneWidget);
195	      expect(find.byType(Switch), findsOneWidget);
196	      expect(find.text('Entrar com biometria'), findsOneWidget);
197	    },
198	  );
199	
200	  testWidgets(
201	    'the switch mirrors currentBiometricEnabled (true) at construction',
202	    (tester) async {
203	      await _pumpScreen(tester);
204	
205	      final switchWidget = tester.widget<Switch>(find.byType(Switch));
206	      expect(switchWidget.value, isTrue);
207	    },
208	  );
209	
210	  testWidgets(
211	    'a false currentBiometricEnabled (already fetched before the screen '
212	    'opened) renders the switch off',
213	    (tester) async {
214	      final fakeRepository = _FakeAccountSettingsRepository().._emit(false);
215	      final cubit = AccountSettingsCubit(fakeRepository);
216	      addTearDown(() => cubit.close());
217	      addTearDown(fakeRepository.dispose);
218	
219	      final router = _routerWith(
220	        AccountSettingsScreen(
221	          cubit: cubit,
222	          dashboardCubit: _buildDashboardCubit(),
223	        ),
224	      );
225	      addTearDown(router.dispose);
226	      await tester.pumpWidget(MaterialApp.router(routerConfig: router));
227	
228	      final switchWidget = tester.widget<Switch>(find.byType(Switch));
229	      expect(switchWidget.value, isFalse);
230	    },
231	  );
232	
233	  testWidgets(
234	    'tapping the switch calls toggleBiometric() with the requested value and '
235	    'flips the rendered switch — no error band on success',
236	    (tester) async {
237	      final (fakeRepository, _) = await _pumpScreen(tester);
238	      fakeRepository.setBiometricEnabledResult = right(unit);
239	
240	      await tester.tap(find.byType(Switch));
241	      await tester.pumpAndSettle();
242	
243	      final switchWidget = tester.widget<Switch>(find.byType(Switch));
244	      expect(switchWidget.value, isFalse);
245	      // No error text rendered — only the label and the back-arrow title.
246	      expect(find.textContaining('conexão'), findsNothing);
247	    },
248	  );
249	
250	  testWidgets(
251	    'a failed toggle reverts the switch and shows the Failure\'s message '
252	    'inline, below the toggle row',
253	    (tester) async {
254	      final (fakeRepository, _) = await _pumpScreen(tester);
255	      fakeRepository.setBiometricEnabledResult = left(
256	        const Failure.networkTimeout(message: 'Sem conexão'),
257	      );
258	
259	      await tester.tap(find.byType(Switch));
260	      await tester.pumpAndSettle();
261	
262	      final switchWidget = tester.widget<Switch>(find.byType(Switch));
263	      expect(switchWidget.value, isTrue);
264	      expect(find.text('Sem conexão'), findsOneWidget);
265	    },
266	  );
267	
268	  testWidgets('the switch disables itself while a toggle is in flight, so a '
269	      'double-tap can never start a second, overlapping call (review '
270	      'finding)', (tester) async {
271	    final (fakeRepository, _) = await _pumpScreen(tester);
272	    fakeRepository.setBiometricEnabledResult = right(unit);
273	    fakeRepository.setBiometricEnabledGate = Completer<void>();
274	
275	    await tester.tap(find.byType(Switch));
276	    await tester.pump();
277	
278	    var switchWidget = tester.widget<Switch>(find.byType(Switch));
279	    expect(switchWidget.onChanged, isNull);
280	
281	    fakeRepository.setBiometricEnabledGate!.complete();
282	    await tester.pumpAndSettle();
283	
